import{_ as t,a0 as p,w as o,s as h,I as l,x as n,a1 as e,A as i,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何打包你的 Python 代碼 | LCTT x X-CMD","titleTemplate":false,"description":"如何打包你的 Python 代碼 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何打包你的 Python 代碼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何打包你的 Python 代碼 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211109 How to package your Python code","title":"如何打包你的 Python 代碼","tag":"202111","desc":""},"relativePath":"202111/20211109 How to package your Python code.md","filePath":"[post].md"}'),r={name:"202111/20211109 How to package your Python code.md"};function u(g,s,b,c,y,k){const a=p("Link");return o(),h("div",null,[s[25]||(s[25]=l("h1",{id:"如何打包你的-python-代碼",tabindex:"-1"},[n("如何打包你的 Python 代碼 "),l("a",{class:"header-anchor",href:"#如何打包你的-python-代碼","aria-label":"Permalink to “如何打包你的 Python 代碼”"},"​")],-1)),s[26]||(s[26]=l("blockquote",null,[l("p",null,"使用 setuptools 來向用户交付 Python 代碼。")],-1)),s[27]||(s[27]=l("p",null,[l("img",{src:"https://img.linux.net.cn/data/attachment/album/202111/17/180249s8s1cnnn18gh3fsk.jpg",alt:""})],-1)),l("p",null,[s[1]||(s[1]=n("你花了幾周的時間來完善你的代碼。你已經對它進行了測試，並把它發送給一些親近的開發者朋友以保證質量。你已經將所有的源代碼發佈在 ",-1)),e(a,{href:"https://opensource.com/life/16/8/how-construct-your-own-git-server-part-6"},{default:i(()=>[...s[0]||(s[0]=[n("你的個人 Git 服務器",-1)])]),_:1}),s[2]||(s[2]=n(" 上，並且從一些勇敢的早期使用者收到了一些有用的錯誤報告。現在你已經準備好將你的 Python 代碼提供給全世界。",-1))]),s[28]||(s[28]=l("p",null,"就在這時你遇到一個問題。你不知道如何交付產品。",-1)),l("p",null,[s[5]||(s[5]=n("將代碼交付給它的目標用户是一件大事。這是軟件開發的一個完整的分支，是 CI/CD 中的 “D”，但很多人都忘記了，至少到最後才知道。我寫過關於 ",-1)),e(a,{href:"https://opensource.com/article/19/7/introduction-gnu-autotools"},{default:i(()=>[...s[3]||(s[3]=[n("Autotools",-1)])]),_:1}),s[6]||(s[6]=n(" 和 ",-1)),e(a,{href:"https://opensource.com/article/21/5/cmake"},{default:i(()=>[...s[4]||(s[4]=[n("Cmake",-1)])]),_:1}),s[7]||(s[7]=n(" 的文章，但有些語言有自己的方法來幫助你將你的代碼提供給用户。對於 Python 來説，向用户提供代碼的一個常見方法是使用 ",-1)),s[8]||(s[8]=l("code",null,"setuptools",-1)),s[9]||(s[9]=n("。",-1))]),s[29]||(s[29]=d(`<h3 id="安裝-setuptools" tabindex="-1">安裝 setuptools <a class="header-anchor" href="#安裝-setuptools" aria-label="Permalink to “安裝 setuptools”">​</a></h3><p>安裝和更新 <code>setuptools</code> 的最簡單方法是使用 <code>pip</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo python -m pip install --upgrade setuptools</span></span></code></pre></div><h3 id="示例庫" tabindex="-1">示例庫 <a class="header-anchor" href="#示例庫" aria-label="Permalink to “示例庫”">​</a></h3><p>我創建了一個簡單的 Python 庫，名為 <code>myhellolib</code>，來作為需要打包的示例代碼。這個庫接受一個字符串，然後用大寫字母打印出這個字符串。</p><p>它只有兩行代碼，但項目結構很重要，所以首先創建目錄樹：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir -p myhellolib.git/myhellolib</span></span></code></pre></div><p>為了確認這個項目是一個可導入的庫（即 Python “模組”），在代碼目錄中創建一個空文件 <code>__init__.py</code>，同時創建一個包含代碼的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch myhellolib.git/myhellolib/__init__.py</span></span>
<span class="line"><span>$ touch myhellolib.git/myhellolib/myhellolib.py</span></span></code></pre></div><p>在 <code>myhellolib.py</code> 文件中，輸入簡單的 Python 代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def greeter(s):</span></span>
<span class="line"><span>    print(s.upper())</span></span></code></pre></div><p>這就是寫好的庫。</p><h3 id="測試它" tabindex="-1">測試它 <a class="header-anchor" href="#測試它" aria-label="Permalink to “測試它”">​</a></h3><p>在打包之前，測試一下你的庫。創建一個 <code>myhellolib.git/test.py</code> 文件並輸入以下代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import myhellolib.myhellolib as hello</span></span>
<span class="line"><span>hello.greeter(&quot;Hello Opensource.com.&quot;)</span></span></code></pre></div><p>運行該腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd myhellolib.git</span></span>
<span class="line"><span>$ python ./test.py</span></span>
<span class="line"><span>HELLO OPENSOURCE.COM</span></span></code></pre></div><p>它可以工作，所以現在你可以把它打包了。</p><h3 id="setuptools" tabindex="-1">Setuptools <a class="header-anchor" href="#setuptools" aria-label="Permalink to “Setuptools”">​</a></h3><p>要用 <code>setuptools</code> 打包一個項目，你必須創建一個 <code>.toml</code> 文件，將 <code>setuptools</code> 作為構建系統。將這段文字放在項目目錄下的 <code>myhellolib.toml</code> 文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[build-system]</span></span>
<span class="line"><span>requires = [&quot;setuptools&quot;, &quot;wheel&quot;]</span></span>
<span class="line"><span>build-backend = &quot;setuptools.build_meta&quot;</span></span></code></pre></div><p>接下來，創建一個名為 <code>setup.py</code> 的文件，包含項目的元數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from setuptools import setup</span></span>
<span class="line"><span></span></span>
<span class="line"><span>setup(</span></span>
<span class="line"><span>   name=&#39;myhellolib&#39;,</span></span>
<span class="line"><span>   version=&#39;0.0.1&#39;,</span></span>
<span class="line"><span>   packages=[&#39;myhellolib&#39;],</span></span>
<span class="line"><span>   install_requires=[</span></span>
<span class="line"><span>      &#39;requests&#39;,</span></span>
<span class="line"><span>      &#39;importlib; python_version == &quot;3.8&quot;&#39;,</span></span>
<span class="line"><span>   ],</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>不管你信不信，這就是 <code>setuptools</code> 需要的所有設置。你的項目已經可以進行打包。</p><h3 id="打包-python" tabindex="-1">打包 Python <a class="header-anchor" href="#打包-python" aria-label="Permalink to “打包 Python”">​</a></h3><p>要創建你的 Python 包，你需要一個構建器。一個常見的工具是 <code>build</code>，你可以用 <code>pip</code> 安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python -m pip install build --user</span></span></code></pre></div><p>構建你的項目：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python -m build</span></span></code></pre></div><p>過了一會兒，構建完成了，在你的項目文件夾中出現了一個新的目錄，叫做 <code>dist</code>。這個文件夾包含一個 <code>.tar.gz</code> 和一個 <code>.whl</code> 文件。</p><p>這是你的第一個 Python 包! 下面是包的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar --list --file dist/myhellolib-0.0.1.tar.gz</span></span>
<span class="line"><span>myhellolib-0.0.1/</span></span>
<span class="line"><span>myhellolib-0.0.1/PKG-INFO</span></span>
<span class="line"><span>myhellolib-0.0.1/myhellolib/</span></span>
<span class="line"><span>myhellolib-0.0.1/myhellolib/__init__.py</span></span>
<span class="line"><span>myhellolib-0.0.1/myhellolib/myhellolib.py</span></span>
<span class="line"><span>myhellolib-0.0.1/myhellolib.egg-info/</span></span>
<span class="line"><span>myhellolib-0.0.1/myhellolib.egg-info/PKG-INFO</span></span>
<span class="line"><span>myhellolib-0.0.1/myhellolib.egg-info/SOURCES.txt</span></span>
<span class="line"><span>myhellolib-0.0.1/myhellolib.egg-info/dependency_links.txt</span></span>
<span class="line"><span>myhellolib-0.0.1/myhellolib.egg-info/requires.txt</span></span>
<span class="line"><span>myhellolib-0.0.1/myhellolib.egg-info/top_level.txt</span></span>
<span class="line"><span>myhellolib-0.0.1/setup.cfg</span></span>
<span class="line"><span>myhellolib-0.0.1/setup.py</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ unzip -l dist/myhellolib-0.0.1-py3-none-any.whl </span></span>
<span class="line"><span>Archive:  dist/myhellolib-0.0.1-py3-none-any.whl</span></span>
<span class="line"><span>Name</span></span>
<span class="line"><span>----</span></span>
<span class="line"><span>myhellolib/__init__.py</span></span>
<span class="line"><span>myhellolib/myhellolib.py</span></span>
<span class="line"><span>myhellolib-0.0.1.dist-info/METADATA</span></span>
<span class="line"><span>myhellolib-0.0.1.dist-info/WHEEL</span></span>
<span class="line"><span>myhellolib-0.0.1.dist-info/top_level.txt</span></span>
<span class="line"><span>myhellolib-0.0.1.dist-info/RECORD</span></span>
<span class="line"><span>-------</span></span>
<span class="line"><span>6 files</span></span></code></pre></div><h3 id="讓它可用" tabindex="-1">讓它可用 <a class="header-anchor" href="#讓它可用" aria-label="Permalink to “讓它可用”">​</a></h3><p>現在你知道了打包你的 Python 包是多麼容易，你可以使用 Git 鈎子、GitLab Web 鈎子、Jenkins 或類似的自動化工具來自動完成這個過程。你甚至可以把你的項目上傳到 PyPi，這個流行的 Python 模組倉庫。一旦它在 PyPi 上，用户就可以用 <code>pip</code> 來安裝它，就像你在這篇文章中安裝 <code>setuptools</code> 和 <code>build</code> 一樣！</p><p>當你坐下來開發一個應用或庫時，打包並不是你首先想到的事情，但它是編程的一個重要方面。Python 開發者在程序員如何向世界提供他們的工作方面花了很多心思，沒有比 <code>setuptools</code> 更容易的了。試用它，使用它，並繼續用 Python 編碼！</p><hr>`,36)),l("p",null,[s[11]||(s[11]=n("via: ",-1)),e(a,{href:"https://opensource.com/article/21/11/packaging-python-setuptools"},{default:i(()=>[...s[10]||(s[10]=[n("https://opensource.com/article/21/11/packaging-python-setuptools",-1)])]),_:1})]),l("p",null,[s[16]||(s[16]=n("作者：",-1)),e(a,{href:"https://opensource.com/users/seth"},{default:i(()=>[...s[12]||(s[12]=[n("Seth Kenlon",-1)])]),_:1}),s[17]||(s[17]=n(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[13]||(s[13]=[n("lujun9972",-1)])]),_:1}),s[18]||(s[18]=n(" 譯者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:i(()=>[...s[14]||(s[14]=[n("geekpi",-1)])]),_:1}),s[19]||(s[19]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[15]||(s[15]=[n("wxy",-1)])]),_:1})]),l("p",null,[s[22]||(s[22]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[20]||(s[20]=[n("LCTT",-1)])]),_:1}),s[23]||(s[23]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...s[21]||(s[21]=[n("Linux中國",-1)])]),_:1}),s[24]||(s[24]=n(" 榮譽推出",-1))])])}const P=t(r,[["render",u]]);export{C as __pageData,P as default};
